#!/usr/bin/env python3
"""COSMOS v9.3.3 guarded photo editor + full-screen backgrounds.
Does not deploy Workers, edit D1, remove posts, touch authentication, or change Jobs APIs.
Supports the exact v9.3.1 and v9.3.2 frontends; preserves v9.3.2 functionality.
"""
import base64, hashlib, os, subprocess, sys, tempfile, zlib
from pathlib import Path
from html.parser import HTMLParser
MODE=sys.argv[1] if len(sys.argv)>1 else 'validate'
if MODE not in ('validate','apply'):raise SystemExit('Usage: validate or apply')
TARGET='af2e9581f49dacd1fd4eedeb07c685de8dcd0a56125f0d06952931289259708e'
PATCHES={
 'eb021d96e4c436d31d0b74148eb70fb5dd3a0ccc7e169f9a5b2ae11b04bf202f': '',
 '964e144b1c81b069d6b7434e807ff3d56e792c23d16892a916acaf05bd86ae49': '',
}
class Scripts(HTMLParser):
 def __init__(self):super().__init__();self.in_script=False;self.js=[]
 def handle_starttag(self,tag,attrs):
  if tag=='script' and not dict(attrs).get('src'):self.in_script=True;self.buffer=''
 def handle_data(self,data):
  if self.in_script:self.buffer+=data
 def handle_endtag(self,tag):
  if tag=='script' and self.in_script:self.js.append(self.buffer);self.in_script=False
source=Path('cosmos-next.html')
if not source.is_file():raise SystemExit('Missing cosmos-next.html at repository root')
before=source.read_bytes();digest=hashlib.sha256(before).hexdigest()
if digest==TARGET:
 print('ALREADY APPLIED: v9.3.3 frontend is installed. No changes needed.');raise SystemExit(0)
if digest not in PATCHES:
 raise SystemExit('SAFE STOP: unexpected cosmos-next.html checksum '+digest+'; no files changed. Upload your newest source for reconciliation.')
with tempfile.TemporaryDirectory() as d:
 folder=Path(d);(folder/'cosmos-next.html').write_bytes(before)
 patch=folder/'update.patch';patch.write_bytes(zlib.decompress(base64.b64decode(PATCHES[digest])))
 result=subprocess.run(['patch','-p1','--batch','--forward','-i',str(patch)],cwd=folder,capture_output=True,text=True)
 if result.returncode:raise SystemExit('SAFE STOP: could not apply verified photo patch. '+result.stderr[:1000])
 final=(folder/'cosmos-next.html').read_bytes()
 if hashlib.sha256(final).hexdigest()!=TARGET:raise SystemExit('SAFE STOP: target checksum mismatch. Nothing changed.')
 html=final.decode('utf-8');checks=[
  'cosmos933InitShell','cosmos933EditPhoto','cosmos933Upload',
  'cosmos933-has-personal-bg','cosmos933-has-business-bg',
  '/api/identity-media/','jobsResumeUpload','/api/business/jobs/discover',
  'cosmos929-origin-orb','business-metro-shell','id="cosmosChoosePrivate"']
 for item in checks:
  if item not in html:raise SystemExit('SAFE STOP: required existing UI missing '+item)
 parser=Scripts();parser.feed(html)
 if len(parser.js)!=4:raise SystemExit('SAFE STOP: expected four inline scripts')
 for i,js in enumerate(parser.js):
  f=folder/('inline_'+str(i)+'.js');f.write_text(js)
  ck=subprocess.run(['node','--check',str(f)],capture_output=True,text=True)
  if ck.returncode:raise SystemExit('SAFE STOP: inline JavaScript '+str(i)+' syntax failed: '+ck.stderr[:800])
 print('PASS: exact source checksum; preserve COSMOS authentication, moments, Jobs, marketplaces and four scripts.')
 if MODE=='validate':print('VALIDATION ONLY: cosmos-next.html unchanged.')
 else:
  temp=source.with_name('.cosmos-next-v933.temp');temp.write_bytes(final);os.replace(temp,source)
  print('APPLIED: v9.3.3 photo/editor/background frontend safely installed.')
